import {describe,it,expect} from 'vitest';import {BuildSystem} from '../src/game/build-system.js';
describe('BuildSystem',()=>{it('snaps and rejects overlap',()=>{const b=new BuildSystem();expect(b.placeForm('foundation',{x:.24,y:0,z:.26}).position).toEqual({x:0,y:0,z:.5});expect(b.placeForm('foundation',{x:.1,y:0,z:.3}).error).toBe('occupied')});it('fills and cures',()=>{const b=new BuildSystem();const f=b.placeForm('foundation',{x:0,y:0,z:0});expect(b.pour(f.id,500,.9)).toBe(220);expect(f.state).toBe('wet');b.update(6);expect(f.state).toBe('setting');b.update(60);expect(f.state).toBe('cured')});it('rejects unsupported elevated slabs',()=>{const b=new BuildSystem();expect(b.placeForm('slab',{x:0,y:3,z:0}).error).toBe('unsupported')});it('removes a misplaced form',()=>{const b=new BuildSystem();const f=b.placeForm('column',{x:1,y:0,z:1});expect(b.remove(f.id)).toBe(f);expect(b.forms).toHaveLength(0);expect(b.remove(999)).toBeNull()})});
